using FMOD.Studio;
using FMODUnity;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class UnitDialogue : MonoBehaviour
{
	[Header("Start of Battle")]
	[SerializeField]
	private float startOfBattleDialogueDelay;

	[Header("Components")]
	[SerializeField]
	private bool enableDialogueBoxGameObject;

	[SerializeField]
	[ShowIf("enableDialogueBoxGameObject")]
	private DialogueBox dialogueBoxGameObject;

	[SerializeField]
	[HideIf("enableDialogueBoxGameObject")]
	private GameObject dialogueBoxPrefab;

	[SerializeField]
	[HideIf("enableDialogueBoxGameObject")]
	private Transform dialogueBoxPosition;

	[SerializeField]
	[HideIf("enableDialogueBoxGameObject")]
	private TransformReference purifyCorruptFeedbackCanvasTransformReference;

	[SerializeField]
	[HideIf("enableDialogueBoxGameObject")]
	private bool invertedDialogueBox;

	[Header("Show Then Hide Dialogue Box")]
	[SerializeField]
	private bool enableOverrideTimeToHideDialogueBox;

	[SerializeField]
	[ShowIf("enableOverrideTimeToHideDialogueBox")]
	private float overrideTimeToHideDialogueBox;

	[Header("Character")]
	[SerializeField]
	private bool character;

	[SerializeField]
	[ShowIf("character")]
	private bool customCharacter;

	[Header("SFX")]
	[SerializeField]
	private bool enableDialogueSFX;

	[SerializeField]
	[ShowIf("enableDialogueSFX")]
	private EventReference dialogueSFX;

	private DialogueData dialogueData;

	private bool hasDialogueData;

	private DialogueBox dialogueBox;

	private EventInstance unitTalkingEventInstance;

	private bool showingDialogueBox;

	public DialogueBox DialogueBoxGameObject => dialogueBoxGameObject;

	public Transform DialogueBoxPosition => dialogueBoxPosition;

	public float OverrideTimeToHideDialogueBox => overrideTimeToHideDialogueBox;

	public bool TextShowed => dialogueBox.TextShowed;

	private void Awake()
	{
		if (enableDialogueBoxGameObject)
		{
			dialogueBox = dialogueBoxGameObject;
		}
		if (character && !customCharacter)
		{
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.EnableDialogueBoxPositionAdjustment)
			{
				dialogueBoxPosition.GetComponent<RectTransform>().anchoredPosition = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.DialogueBoxPositionAdjustment;
			}
			enableDialogueSFX = true;
			dialogueSFX = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterSFXData.Talking;
		}
	}

	public void Initialize(Character character)
	{
		if (character.EnableDialogueBoxPositionAdjustmentTransform)
		{
			dialogueBoxPosition.transform.localPosition = character.DialogueBoxPositionAdjustmentTransform;
		}
		enableDialogueSFX = true;
		dialogueSFX = character.CharacterSFXData.Talking;
	}

	public void Initialize(DialogueData dialogueData)
	{
		this.dialogueData = dialogueData;
		hasDialogueData = dialogueData != null;
	}

	public void SetInvertedDialogueBox(bool invertedDialogueBox)
	{
		this.invertedDialogueBox = invertedDialogueBox;
	}

	public bool HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum dialogueTypeEnum, bool showThenHide = true, bool warningDialogueBox = false)
	{
		if (!hasDialogueData)
		{
			return false;
		}
		bool num = dialogueData.HasDialogueType(dialogueTypeEnum);
		if (num)
		{
			ShowDialogueBoxRandomDialogue(dialogueTypeEnum, showThenHide, warningDialogueBox);
		}
		return num;
	}

	private void ShowDialogueBoxRandomDialogue(DialogueTypeEnum dialogueTypeEnum, bool showThenHide, bool warningDialogueBox = false)
	{
		string localizedDialogue = dialogueData.GetRandomDialogueID(dialogueTypeEnum);
		if (showThenHide)
		{
			if (dialogueTypeEnum == DialogueTypeEnum.STARTOFBATTLE)
			{
				InvokeAlternatives.Invoke(this, startOfBattleDialogueDelay, delegate
				{
					ShowDialogueBoxThenHide(localizedDialogue, warningDialogueBox);
				});
			}
			else
			{
				ShowDialogueBoxThenHide(localizedDialogue, warningDialogueBox);
			}
		}
		else
		{
			ShowDialogueBox(localizedDialogue);
		}
	}

	private void ShowDialogueBoxThenHide(string dialogueString, bool warningDialogueBox = false)
	{
		PlayDialogueSFX();
		if (!enableDialogueBoxGameObject)
		{
			InstantiateDialogueBox(warningDialogueBox);
		}
		else
		{
			dialogueBox.gameObject.SetActive(value: true);
		}
		dialogueBox.PopulateShowDialogueBoxThenHide(dialogueString, !enableDialogueBoxGameObject, enableOverrideTimeToHideDialogueBox ? overrideTimeToHideDialogueBox : 0f);
		if (!enableDialogueBoxGameObject)
		{
			dialogueBox = null;
		}
	}

	private void InstantiateDialogueBox(bool warningDialogueBox = false)
	{
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(dialogueBoxPrefab.name, purifyCorruptFeedbackCanvasTransformReference.value);
		@object.transform.position = dialogueBoxPosition.position;
		dialogueBox = @object.GetComponent<DialogueBox>();
		dialogueBox.Initialize(invertedDialogueBox, warningDialogueBox);
	}

	private void ShowDialogueBox(string dialogueString)
	{
		PlayDialogueSFX();
		if (!enableDialogueBoxGameObject)
		{
			InstantiateDialogueBox();
		}
		else
		{
			dialogueBox.gameObject.SetActive(value: true);
		}
		dialogueBox.PopulateShowDialogueBox(dialogueString);
	}

	public void HideDialogueBox()
	{
		if (!enableDialogueBoxGameObject)
		{
			dialogueBox.HideDialogueBox(storeObject: true);
		}
		else if (dialogueBox.gameObject.activeInHierarchy)
		{
			dialogueBox.HideDialogueBox(delegate
			{
				dialogueBox.gameObject.SetActive(value: false);
			});
		}
	}

	public void StartUnitDialogue()
	{
		if (!enableDialogueBoxGameObject)
		{
			InstantiateDialogueBox();
		}
		PlayDialogueSFX();
		dialogueBox.PopulateShowDialogueBox(GetDialogue(0));
	}

	public void NextDialogue(int dialogueIndex)
	{
		PlayDialogueSFX();
		dialogueBox.PopulateShowDialogueBox(GetDialogue(dialogueIndex));
	}

	public void SkipTypeWritting()
	{
		dialogueBox.SkipTypewritting();
	}

	private string GetDialogue(int index)
	{
		return dialogueData.GetDialogue(DialogueTypeEnum.DIALOGUE, index);
	}

	private string GetLocalizedDialogue(string stringID)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(stringID);
	}

	public void PlayDialogueSFX()
	{
		if (enableDialogueSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlayOneInstanceOnlySFX(ref unitTalkingEventInstance, dialogueSFX);
		}
	}

	public void OnSwitchBetweenSentinelUpgradeAndNewSentinelButtonPressed()
	{
		HideDialogueBox();
	}

	public void OnShowThenHideDialogueCustomizedPlayer(string dialogueString)
	{
		if (!showingDialogueBox)
		{
			showingDialogueBox = true;
			ShowDialogueBoxThenHide(dialogueString, warningDialogueBox: true);
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enableOverrideTimeToHideDialogueBox ? overrideTimeToHideDialogueBox : dialogueBox.TimeToHideDialogueBox, delegate
			{
				showingDialogueBox = false;
			});
		}
	}

	public void OnShowThenHideDialogueCustomizedSaiph(string dialogueString)
	{
		OnShowThenHideDialogueCustomizedPlayer(dialogueString);
	}

	public void SetOverrideTimeToHideDialogueBox(float overrideTimeToHideDialogueBox)
	{
		this.overrideTimeToHideDialogueBox = overrideTimeToHideDialogueBox;
	}
}
